// ToggleProps are the params of a Toggle, by their names in the kit (comp/toggle.js). A param that is not given keeps
// the default written next to it.
type ToggleProps struct {
	Key             any    // default: "0"
	Width           any    // default: 70. Standard box features are added automatically.
	Height          any    // default: 40
	Spacing         any    // default: 3. px: between the track and the knob
	Value           any    // default: 0
	InvertColor     any    // default: 0
	OffButtonScale  any    // default: 0.6. The size of the knob when off. (1: the same size as on)
	OnMark          any    // default: a function. Shows when on: "check", "cross" or a text ("ON"). "": nothing
	OffMark         string // default: "". Shows when off
	MarkPlace       string // default: "track". "track": on the free side of the track, "knob": in the knob (Only at create time)
	Animated        any    // default: 1. 1: small motions of a toggle with marks. (box.setAnimated(0/1))
	FocusRingColor  string // default: "". the ring of the keyboard focus. "": the ring of basic.js
	MarkStyle       P      // default: {...}
	OnChange        any    // default: a function. self.value changed (a click, a key, setValue()). Not at create time, not with setValue(value, 1)
	BackgroundStyle P      // default: {...}. The track
	ButtonStyle     P      // default: {...}. The knob
	StyleName       string // default: "ozden". "ozden", "ozdenDark", "light", "dark", "classic", "float", "round", "slim", "outline", "square", "tick", "badge", "label", "minimal", "minimalDark" or a name added to Toggle.styles
	Style           P      // default: {}. WHY: the look is in the params above; the packages are packages of params (see Toggle.styles).

	Left     any // with Top: a place of its own in a Box or on the page
	Top      any
	Visible  any
	Opacity  any
	Fill     bool // it takes the room the other objects of its group leave
	Unframed bool // no border and no rounded corners on its box (it fills the room between two bars)
	Extra    P    // any other value, by its name in the kit
}

