type TreeViewProps struct {
	Key                 any    // default: "0"
	Width               any    // default: 260
	Height              any    // default: 320. "auto": no scrolling, the tree grows with its rows.
	Items               any    // default: []. [NODE] (See NODE above)
	Value               any    // default: null. Key of the selected node. null: nothing is selected.
	EmptyText           string // default: "No items"
	TypeAhead           any    // default: 1. 1: Typing a letter jumps to the next row that starts with it.
	UseScrollBar        any    // default: 1. basic/scroll-bar.js (when it is loaded). 0: the scrollbar of the browser.
	Enabled             any    // default: 1
	AriaLabel           string // default: "Tree"
	OnSelect            any    // default: a function. self.value, self.previousValue
	OnActivate          any    // default: a function. Double click or Enter (event.type: "dblclick" or "keydown")
	ToggleOnDoubleClick any    // default: 1. 0: a double click does not open / close the row (Ex: it renames it)
	OnToggle            any    // default: a function. node.expanded: 1 or 0
	OnHover             any    // default: a function. node: null when the mouse leaves the rows
	OnLoadChildren      any    // default: a function. hasChildren: 1 and no children. Call self.setChildren(node.key, [...]).
	StyleName           string // default: "light". "light" ("classic": its old name), "modern", "dark", "minimal", "minimalDark" or a name added to TreeView.styles
	Style               P      // default: {...}. Light style package (default)

	Left     any // with Top: a place of its own in a Box or on the page
	Top      any
	Visible  any
	Opacity  any
	Fill     bool // it takes the room the other objects of its group leave
	Unframed bool // no border and no rounded corners on its box (it fills the room between two bars)
	Extra    P    // any other value, by its name in the kit
}

