// WebViewProps are the params of a WebView, by their names in the kit (comp/web-view.js). A param that is not given keeps
// the default written next to it.
type WebViewProps struct {
	Key            any    // default: "0"
	Width          any    // default: 400
	Height         any    // default: 300
	Url            string // default: "". "": Nothing is loaded (placeholder is shown)
	HtmlText       string // default: "". HTML text instead of a URL (srcdoc). NOTE: Not "html": that is the innerHTML setter of a basic.js Box.
	AriaLabel      string // default: "Web view". the name a screen reader says (the title of the iframe)
	Sandbox        any    // default: null. null: No sandbox. Ex: "allow-scripts allow-same-origin allow-forms allow-popups"
	Allow          string // default: "". Ex: "fullscreen; clipboard-write"
	ReferrerPolicy string // default: "". Ex: "no-referrer"
	Lazy           any    // default: 0. 1: The browser loads the page when the box is near the screen. (loading="lazy")
	Scale          any    // default: 1. 0.5: The page is shown at half size (scaled preview). NOTE: Not "zoom": basic.js uses it for the page.
	Interactive    any    // default: 1. 0: The page can not be clicked or scrolled. (Preview)
	AutoHeight     any    // default: 0. 1: The box height follows the page height. (Same origin pages only)
	Toolbar        any    // default: 0. 1: A bar with the URL, reload and "open in a new tab" buttons (Only at create time)
	ShowLoading    any    // default: 1. 1: Spinner until the page is loaded
	EmptyText      string // default: "No page". Shown when nothing is loaded
	LoadTimeout    any    // default: 0. Seconds. 0: No timeout. Ex: 15 -> onTimeout is called when the page is not loaded in 15 seconds.
	OnLoad         any    // default: a function
	OnError        any    // default: a function. Same origin URL of load() that could not be loaded (the browser shows its error page)
	OnTimeout      any    // default: a function
	OnMessage      any    // default: a function. Messages from the page (window.parent.postMessage)
	OnClick        any    // default: a function. interactive: 0 -> click on the cover
	Style          P      // default: {...}

	Left      any // with Top: a place of its own in a Box or on the page
	Top       any
	StyleName string // the package of its look (see the function)
	Visible   any
	Opacity   any
	Fill      bool // it takes the room the other objects of its group leave
	Unframed  bool // no border and no rounded corners on its box (it fills the room between two bars)
	Extra     P    // any other value, by its name in the kit
}

